(function(){
'use strict';
const KEY='study-library-v1',DB='study-library-files-v1';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const icon=(name='book')=>`<svg class="s-icon" viewBox="0 0 24 24" aria-hidden="true">${({book:'<path d="M3 4c3-1 6-1 9 1v16c-3-2-6-2-9-1zM21 4c-3-1-6-1-9 1v16c3-2 6-2 9-1z"/>',home:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M9 9h12"/>',plus:'<path d="M12 4v16M4 12h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',back:'<path d="M14 5l-7 7 7 7M7 12h14"/>',save:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>'})[name]}</svg>`;
const seedCourses=[['unix','유닉스 프로그래밍'],['programming-languages','프로그래밍언어론'],['discrete-math','이산수학'],['data-centric-ml','데이터중심머신러닝'],['data-communication','데이터통신']].map(([id,name])=>({id,name,grade:2,semester:'2',year:'',questions:[],exam:{mid:{},final:{}}}));
const seedMaterials=[['w01','강의 소개와 Linux',29],['w02','Linux 명령어·vi·Makefile',75],['w06','파일 시스템과 파일 입출력',73]].map(([unit,title,pages])=>({id:'unix-'+unit,course:'unix',title:unit+' · '+title,unit,pages,filename:unit+'. 강의자료.pdf',builtin:true,url:`original/${unit}.pdf`,week:unit,archived:false}));
seedCourses[0].exam.mid=Object.fromEntries(seedMaterials.map(m=>[m.id,'전체']));
let state,storageError=false,viewGrade=2,viewSemester='2',viewYear='',activeCourse=null,activeTab='home',examType='mid',archiveView=false,routeNumber=0,objectURLs=[];
try{const raw=localStorage.getItem(KEY);if(raw){const value=JSON.parse(raw);if(!Array.isArray(value.courses)||!Array.isArray(value.materials)||!value.courses.some(c=>c.id==='unix'))throw Error();state=value;}}catch{storageError=true;}
if(!state)state={version:1,courses:structuredClone(seedCourses),materials:structuredClone(seedMaterials)};
for(const ch of window.COURSE_CHAPTERS){if(!state.courses.some(c=>c.id==='programming-languages'))state.courses.push(structuredClone(seedCourses[1]));if(!state.materials.some(m=>m.id===ch.id))state.materials.push({id:ch.id,course:'programming-languages',title:ch.title,pages:ch.pages.length,filename:ch.url.split('/').pop(),builtin:true,url:ch.url,chapter:ch.id,week:ch.title,archived:false});}
const examViews={};
const tabs=[['home','과목 홈'],['materials','강의자료'],['textbook','학습 교재'],['exams','시험 준비'],['review','오답 복습'],['questions','확인할 내용']];
const root=document.createElement('div');root.id='school-app';root.hidden=true;document.body.insertBefore(root,document.body.firstChild);
const modal=document.createElement('dialog');modal.id='s-dialog';document.body.append(modal);
function notify(message){const t=q('#toast');t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',3500);}
function commit(change){const next=structuredClone(state);change(next);try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageError=false;return true;}catch{notify('저장 공간에 기록하지 못했습니다. 기존 자료와 기록은 유지됩니다.');return false;}}
function course(id){return state.courses.find(c=>c.id===id);}
function materials(id,archived=false){return state.materials.filter(m=>m.course===id&&!!m.archived===archived);}
function totalPages(id){return materials(id).reduce((n,m)=>n+(Number(m.pages)||0),0);}
function stats(id){if(id==='unix')return window.UnixReader.stats();return{done:[],wrong:[],answers:0,correct:0,last:null};}
function url(id,tab='home'){return `#/course/${encodeURIComponent(id)}/${tab}`;}
function readerURL(l){return l&&window.LESSONS.some(x=>x.unit===l.unit&&x.page===l.page)?`#${l.unit}/${l.page}/${l.tab||'learn'}`:`#w01/1/${l?.tab||'learn'}`;}
function go(hash){if(location.hash===hash)route();else location.hash=hash;}
function libURL(g=viewGrade,s=viewSemester){return `#/library/${g}/${s}`;}
function status(c){if(c.id==='unix'||c.id==='programming-languages')return '교재 준비됨';return materials(c.id).length?'자료 등록됨 · 교재 미제작':'자료 등록 대기';}
function badge(c){return `<span class="s-status ${c.id==='unix'||c.id==='programming-languages'?'ready':''}">${status(c)}</span>`;}
function rangePages(text,max){if(text.trim()==='전체'){return Number.isInteger(max)&&max>0?Array.from({length:max},(_,i)=>i+1):null;}if(!/^\s*\d+(?:\s*-\s*\d+)?(?:\s*,\s*\d+(?:\s*-\s*\d+)?)*\s*$/.test(text))throw Error('범위는 전체 또는 1-10, 15처럼 입력하세요.');const result=new Set();for(const chunk of text.split(',')){const nums=chunk.split('-').map(x=>+x.trim()),start=nums[0],end=nums[1]??start;if(start<1||end<start||end>10000||(max&&end>max))throw Error(`페이지 범위를 확인하세요.${max?' 이 자료는 '+max+'쪽입니다.':''}`);for(let p=start;p<=end;p++)result.add(p);}return[...result].sort((a,b)=>a-b);}
function examInfo(c,type=examType){const scope=c.exam?.[type]||{},selected=materials(c.id).filter(m=>scope[m.id]);let count=0,unknown=false;for(const m of selected){try{const p=rangePages(scope[m.id],m.pages);if(p)count+=p.length;else unknown=true;}catch{unknown=true;}}return{selected,count,unknown,scope};}
let dbPromise;
function database(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('이 브라우저는 파일 보관을 지원하지 않습니다.'));return;}const request=indexedDB.open(DB,1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('브라우저 파일 보관함을 열 수 없습니다.'));});return dbPromise;}
async function putFile(id,file){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id,file});tx.oncomplete=resolve;tx.onerror=()=>reject(Error('파일 저장 공간이 부족하거나 보관을 허용하지 않는 환경입니다.'));});}
async function getFile(id){const db=await database();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>r.result?resolve(r.result.file):reject(Error('이 브라우저에서 파일을 찾을 수 없습니다. 원본을 다시 등록해 주세요.'));r.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));});}
function openDialog(html){objectURLs.forEach(URL.revokeObjectURL);objectURLs=[];modal.innerHTML=`<div class="s-dialog-close"><button type="button" id="s-dialog-close" class="s-btn">닫기</button></div>${html}`;q('#s-dialog-close').onclick=()=>modal.close();modal.showModal();}
modal.addEventListener('close',()=>{objectURLs.forEach(URL.revokeObjectURL);objectURLs=[];});modal.addEventListener('click',ev=>{if(ev.target===modal)modal.close();});
async function preview(m){try{const file=await getFile(m.id),ext=m.filename.split('.').pop().toLowerCase();let contents='';if(['txt','md','csv'].includes(ext)){contents=`<pre class="original-text" style="max-height:55vh;font-size:17px">${e((await file.text()).slice(0,200000))}</pre>`;}openDialog(`<h2 class="s-safe-name">${e(m.title)}</h2>${contents}<div id="s-file-preview"></div><div class="s-actions"><a id="s-file-download" class="s-btn teal" download="${e(m.filename)}">원본 파일 받기</a></div><p style="font-size:15px">등록한 원본입니다. 해설이나 퀴즈가 자동으로 만들어지는 것은 아닙니다.</p>`);const type=ext==='pdf'?'application/pdf':({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'})[ext]||'application/octet-stream';const blob=new Blob([file],{type}),src=URL.createObjectURL(blob);objectURLs.push(src);q('#s-file-download').href=src;if(ext==='pdf')q('#s-file-preview').innerHTML=`<iframe title="등록한 PDF 원문" src="${src}" style="width:100%;height:55vh;border:1px solid #dce6ee"></iframe>`;else if(type.startsWith('image/'))q('#s-file-preview').innerHTML=`<img src="${src}" alt="${e(m.title)} 원문" style="max-width:100%;max-height:60vh;object-fit:contain">`;else if(!contents)q('#s-file-preview').innerHTML='<p>이 형식은 원본 파일을 받아 해당 프로그램에서 열어 주세요.</p>';}catch(err){notify(err.message);}}
function shelfSidebar(){return `<aside class="s-side" aria-label="학년과 학기"><button id="s-close-menu" class="s-close-menu s-btn" aria-label="서재 목차 닫기">닫기</button><a class="s-brand" href="#/library/2/2">${icon('book')}학습 서재</a><a class="s-home-link" href="#/library/all/all">${icon('home')}전체 서재</a><div class="s-nav-title">학년별 보기</div>${[1,2,3,4].map(g=>`<button class="s-grade ${viewGrade===g?'selected':''}" data-grade="${g}">${g}학년</button>`).join('')}<nav class="s-sems" aria-label="학기">${['1','2'].map(s=>`<a class="s-sem ${viewSemester===s?'selected':''}" href="${libURL(viewGrade==='all'?2:viewGrade,s)}">${s}학기</a>`).join('')}</nav><div class="s-save-hint">${icon('save')}학습 기록과 추가 자료는 이 브라우저에 저장됩니다.</div></aside>`;}
function shell(content,c=null){const crumb=c?`<a href="${libURL(c.grade,c.semester)}">${c.grade}학년 / ${c.semester}학기</a><span>/</span><span>${e(c.name)}</span>`:`내 학습 서재 <span>/</span> ${viewGrade==='all'?'전체 과목':viewGrade+'학년 / '+viewSemester+'학기'}`;return `${shelfSidebar()}<main class="s-main" id="s-content" tabindex="-1"><div class="s-topbar"><button id="s-menu" class="s-mobile-menu s-btn" aria-label="서재 목차 열기" aria-expanded="false">목차</button><div class="s-crumb">${crumb}</div><button id="s-add-course" class="s-btn teal">${icon('plus')}과목 추가</button></div>${content}<div class="s-end">${storageError?'이 브라우저의 저장 상태를 확인해 주세요. 기존 기록을 덮어쓰지 않았습니다.':'이 기기의 브라우저에 저장됩니다. 다른 기기와 자동으로 동기화되지 않습니다.'}</div></main>`;}
function shelf(){const list=state.courses.filter(c=>(viewGrade==='all'||c.grade===viewGrade)&&(viewSemester==='all'||c.semester===viewSemester)&&(!viewYear||(viewYear==='unset'?!c.year:c.year===viewYear)));const years=[...new Set(state.courses.map(c=>c.year).filter(Boolean))].sort().reverse();const unix=list.find(c=>c.id==='unix'),s=stats('unix');return `<div class="s-heading"><h1>${viewGrade==='all'?'내 학습 서재':viewGrade+'학년 '+viewSemester+'학기'}</h1><p>${viewGrade==='all'?'학년·학기별 과목과 학습 기록을 한곳에서 살펴보세요.':'이번 학기의 과목과 학습 기록을 한곳에서 이어가세요.'}</p></div>${unix?`<section class="s-continue"><div><p>이어서 공부하기</p><h2>${e(unix.name)}</h2></div><a class="s-btn teal" href="${readerURL(s.last)}">${icon('book')}교재 열기</a></section>`:''}${years.length?`<div class="s-toolbar"><label>수강 연도<select id="s-year-filter"><option value="">전체 연도</option><option value="unset" ${viewYear==='unset'?'selected':''}>연도 미지정</option>${years.map(y=>`<option ${viewYear===y?'selected':''}>${e(y)}</option>`).join('')}</select></label></div>`:''}<div class="s-list-header"><span>과목</span><span>자료</span><span class="s-status-head">학습 상태</span><span class="sr-only">과목 열기</span></div><div id="s-course-list">${list.map(c=>{const m=materials(c.id),p=totalPages(c.id);return `<div class="s-course-row"><a class="s-course-name" href="${url(c.id)}">${e(c.name)}${c.year?`<small>${e(c.year)}년 수강</small>`:''}</a><span class="s-meta">${m.length?`강의자료 ${m.length}개${p?' · '+p+'쪽':''}`:'등록된 자료 없음'}</span>${badge(c)}<a class="s-btn navy" href="${url(c.id)}">과목 열기</a></div>`;}).join('')||'<div class="s-year-empty">이 학기에 등록한 과목이 없습니다. 과목 추가로 시작하세요.</div>'}</div><div class="s-footnote">${icon('info')}자료와 시험범위는 과목별로 관리합니다.</div>`;}
function courseHeader(c){return `<div class="s-heading"><h1>${e(c.name)}</h1><p>${c.grade}학년 ${c.semester}학기${c.year?' · '+e(c.year)+'년 수강':' · 수강 연도 미지정'}</p></div><nav class="s-course-nav" aria-label="과목 학습 공간">${tabs.map(([id,title])=>`<a class="${activeTab===id?'selected':''}" href="${url(c.id,id)}" ${activeTab===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;}
function empty(c,title='자료 등록 대기',message='강의자료를 등록하면 이 과목의 원문과 시험범위를 정리할 수 있습니다.'){return `<div class="s-empty"><h2>${title}</h2><p>${message}</p><a class="s-btn teal" href="${url(c.id,'materials')}">강의자료 등록하기</a></div>`;}
function home(c){if(c.id==='programming-languages')return textbook(c);const m=materials(c.id),s=stats(c.id),ex=examInfo(c,'mid');return `<section class="s-section">${badge(c)}${c.id==='unix'?`<div class="s-summary"><div>학습 완료<strong>${s.done.length} / 177쪽</strong></div><div>채점한 퀴즈<strong>${s.answers}개</strong></div><div>복습할 오답<strong>${s.wrong.length}개</strong></div></div><div class="s-actions"><a class="s-btn teal" href="${readerURL(s.last)}">이어서 공부하기</a><a class="s-btn" href="${url(c.id,'review')}">오답 복습</a></div>`:`<div class="s-summary"><div>등록한 강의자료<strong>${m.length}개</strong></div><div>학습 교재<strong>미제작</strong></div></div>${empty(c,m.length?'원문 자료부터 살펴보세요':'첫 강의자료를 등록해 주세요',m.length?'등록한 자료는 강의자료에서 열 수 있습니다. 설명과 퀴즈는 제작한 뒤 이 공간에 연결합니다.':'아직 자료를 받지 않은 과목입니다. 근거 없는 설명이나 문제를 미리 만들지 않았습니다.')}`}</section><section class="s-section"><h2>중간고사 범위</h2><p>${ex.selected.length?`${ex.selected.length}개 자료 · ${ex.count}쪽${ex.unknown?' + 쪽수 미지정 자료':''}`:'아직 시험범위를 지정하지 않았습니다.'}</p><div class="s-actions"><a class="s-btn" href="${url(c.id,'exams')}">시험범위 확인·수정</a></div></section><section class="s-section"><div class="s-setup"><p>학년·학기·수강 연도는 과목별로 기록합니다.</p><button id="s-edit-course" class="s-btn">과목 정보 수정</button></div></section>`;}
function materialView(c){const list=materials(c.id,archiveView);return `<section class="s-section"><h2>강의자료</h2><p>자료를 보관하는 곳입니다. 새로 등록한 자료는 시험범위에 자동으로 포함되지 않습니다.</p><div class="s-actions"><button id="s-material-mode" class="s-btn">${archiveView?'현재 자료 보기':'보관함 보기'}</button></div>${list.length?list.map(m=>`<article class="s-material"><div><h3>${e(m.title)}</h3><p>${e(m.week||'주차 미지정')} · ${m.pages?m.pages+'쪽':'쪽수 미지정'} · ${e(m.filename)}</p><small>${m.builtin?'기존 교재에 포함된 원문 PDF':'이 브라우저에 보관한 원본 파일'}</small></div><div class="s-actions">${archiveView?`<button class="s-btn" data-restore="${e(m.id)}">다시 꺼내기</button>`:m.builtin?`<a class="s-btn" href="${m.url}" target="_blank" rel="noopener">원문 PDF</a><a class="s-btn teal" href="${m.chapter?url(c.id,'textbook')+'/'+m.chapter+'/1':'#'+m.unit+'/1/learn'}">교재 보기</a>`:`<button class="s-btn" data-preview="${e(m.id)}">원문 보기</button><button class="s-btn" data-archive="${e(m.id)}">보관함으로</button>`}</div></article>`).join(''):`<div class="s-notice waiting">${archiveView?'보관함에 옮긴 자료가 없습니다.':'등록된 자료가 없습니다. 아래에서 첫 자료를 보관하세요.'}</div>`}</section>${archiveView?'':`<section class="s-section"><h2>자료 등록</h2><p class="s-muted">원본 파일은 이 브라우저에 보관합니다. 과목의 해설·퀴즈가 자동으로 생성되는 기능은 아닙니다.</p><form id="s-material-form" class="s-form"><label class="s-form-field">원본 파일<input id="s-material-file" name="file" type="file" required accept=".pdf,.txt,.md,.csv,.png,.jpg,.jpeg,.webp,.docx,.pptx,.xlsx"><span class="s-help">PDF·텍스트·이미지·Office 파일 / 파일당 최대 30MB</span></label><label class="s-form-field">자료 제목<input name="title" maxlength="180" placeholder="예: 1주차 강의자료"></label><div class="s-form-grid"><label class="s-form-field">주차 또는 분류<input name="week" maxlength="50" placeholder="예: w01 또는 보충자료"></label><label class="s-form-field">총 페이지 수 · 선택<input name="pages" type="number" min="1" max="10000" placeholder="원문을 보고 입력"></label></div><button type="submit" class="s-btn teal">이 과목에 자료 보관</button></form></section>`}`;}
function textbook(c){if(c.id!=='unix')return window.CourseStudy.html(c,materials(c.id));if(c.id!=='unix')return empty(c,materials(c.id).length?'학습 교재 미제작':'자료 등록 대기','이 과목의 해설과 퀴즈는 아직 제작하지 않았습니다. 강의자료를 먼저 보관하고 원문을 읽을 수 있습니다.');return `<section class="s-section"><h2>유닉스 프로그래밍 학습 교재</h2><p>원문과 연결된 177쪽의 해설·퀴즈·실행 실험실입니다. 기존 학습 기록을 이어서 사용합니다.</p><div class="s-actions"><a class="s-btn teal" href="${readerURL(stats(c.id).last)}">이어서 공부하기</a></div>${seedMaterials.map(m=>`<div class="s-info-row"><div><h3>${e(m.title)}</h3><small>${m.pages}쪽 · 페이지별 해설·퀴즈</small></div><a class="s-btn" href="#${m.unit}/1/learn">학습 시작</a></div>`).join('')}</section>`;}
function exams(c){const list=materials(c.id),info=examInfo(c);return `<section class="s-section"><h2>시험 준비</h2><p>보관한 강의자료에서 실제 시험범위를 골라 주세요. 중간고사와 기말고사는 따로 저장합니다.</p><div class="s-exam-switch"><button class="${examType==='mid'?'selected':''}" data-exam="mid">중간고사</button><button class="${examType==='final'?'selected':''}" data-exam="final">기말고사</button></div>${list.length?`<form id="s-scope-form" class="s-form">${list.map(m=>`<div class="s-scope-row"><input type="checkbox" id="scope-${e(m.id)}" name="include" value="${e(m.id)}" ${info.scope[m.id]?'checked':''}><label for="scope-${e(m.id)}">${e(m.title)}<small>${m.pages?m.pages+'쪽':'전체 쪽수 미지정'}</small></label><label><span class="sr-only">${e(m.title)} 페이지 범위</span><input type="text" data-scope-range="${e(m.id)}" value="${e(info.scope[m.id]||'전체')}" placeholder="전체 또는 1-10, 15"></label></div>`).join('')}<p class="s-notice">현재 저장된 범위: ${info.selected.length}개 자료 · ${info.count}쪽${info.unknown?' + 쪽수 미지정 자료':''}<br>페이지는 전체 또는 1-10, 15처럼 입력하세요.</p><button class="s-btn teal" type="submit">시험범위 저장</button></form>${c.id==='unix'&&info.selected.length?`<div class="s-actions"><a class="s-btn" href="${url(c.id,'review')}">오답과 시험범위 비교</a></div>`:''}`:empty(c,'시험범위 지정 대기','먼저 강의자료를 등록해 주세요. 자료를 보관한 뒤 시험에 포함할 파일과 페이지를 고를 수 있습니다.')}</section>`;}
function wrongs(c){if(c.id!=='unix')return window.CourseStudy.review(c,materials(c.id));if(c.id!=='unix')return empty(c,'아직 채점한 문제가 없습니다.','학습 교재와 퀴즈를 제작한 뒤 오답이 과목별로 모입니다.');const wrong=stats(c.id).wrong;const info=examInfo(c);const ids=new Set();for(const m of info.selected){if(m.unit){const ps=rangePages(info.scope[m.id],m.pages)||[];ps.forEach(p=>ids.add(`${m.unit}-${p}`));}}return `<section class="s-section"><h2>오답 복습</h2><p>유닉스 프로그래밍에서 채점한 문제만 표시합니다. 다시 맞힌 문제는 오답 목록에서 빠집니다.</p>${wrong.length?wrong.map(l=>`<a class="s-review-link" href="#${l.unit}/${l.page}/quiz">${e(l.quiz.question)}<small>${l.unit} ${l.page}쪽 · ${e(l.title)}${ids.has(l.id)?' · 현재 '+(examType==='mid'?'중간':'기말')+' 범위':''}</small></a>`).join(''):'<div class="s-notice">현재 복습할 오답이 없습니다. 교재에서 퀴즈를 풀면 결과가 이곳에 연결됩니다.</div>'}<div class="s-actions"><a class="s-btn teal" href="${readerURL({...stats(c.id).last,tab:'quiz'})}">교재 퀴즈 열기</a></div></section>`;}
function questions(c){const rows=c.questions||[];return `<section class="s-section"><h2>확인할 내용</h2><p>강의에서 확인하고 싶은 질문이나 자료의 의심 부분을 기록하세요. 근거와 실제 확인 여부를 나누어 보관합니다.</p>${c.id==='unix'?`<div class="s-notice">기존 교재의 자료 검토 ${window.REVIEWS.length}개도 그대로 연결되어 있습니다. <a href="#w02/60/review">원문·검증 설명·강의 확인 필요 보기</a></div>`:''}${rows.map(n=>`<article class="s-question"><h3>${e(n.text)}</h3>${n.source?`<p>근거: ${e(n.source)}</p>`:''}<label><input type="checkbox" data-question="${e(n.id)}" ${n.resolved?'checked':''}> 실제로 확인 완료</label></article>`).join('')||'<div class="s-notice waiting">직접 기록한 확인 항목이 없습니다.</div>'}<form id="s-question-form" class="s-form"><label class="s-form-field">확인할 질문<textarea name="text" required maxlength="5000" rows="3" placeholder="예: 슬라이드의 설명과 실행 결과가 다른 이유는?"></textarea></label><label class="s-form-field">근거 또는 자료·페이지<input name="source" maxlength="300" placeholder="예: w02 60쪽"></label><button class="s-btn teal" type="submit">이 과목에 질문 기록</button></form></section>`;}
function bindShell(){q('#s-add-course').onclick=()=>courseDialog();qa('[data-grade]').forEach(b=>b.onclick=()=>{viewYear='';go(libURL(+b.dataset.grade,viewSemester==='all'?'2':viewSemester));});q('#s-menu').onclick=()=>{document.body.classList.toggle('s-menu-open');q('#s-menu').setAttribute('aria-expanded',document.body.classList.contains('s-menu-open'));};q('#s-close-menu').onclick=()=>{document.body.classList.remove('s-menu-open');q('#s-menu').setAttribute('aria-expanded','false');q('#s-menu').focus();};if(q('#s-year-filter'))q('#s-year-filter').onchange=ev=>{viewYear=ev.target.value;renderShelf();};}
function renderShelf(){document.title=(viewGrade==='all'?'전체 서재':`${viewGrade}학년 ${viewSemester}학기`)+' | 학습 서재';root.innerHTML=shell(shelf());bindShell();}
function renderCourse(c){const views={home,materials:materialView,textbook,exams,review:wrongs,questions};document.title=c.name+' · '+(tabs.find(x=>x[0]===activeTab)?.[1]||'과목 홈')+' | 학습 서재';root.innerHTML=shell(courseHeader(c)+(views[activeTab]||home)(c),c);bindShell();bindCourse(c);if(activeTab==='textbook'||(c.id==='programming-languages'&&activeTab==='home'))window.CourseStudy.bind(c,materials(c.id));}
function courseDialog(id=null){const c=id?course(id):{name:'',grade:typeof viewGrade==='number'?viewGrade:2,semester:viewSemester==='all'?'2':viewSemester,year:''};openDialog(`<h2>${id?'과목 정보 수정':'과목 추가'}</h2><form id="s-course-form"><label class="s-form-field">과목명<input name="name" maxlength="100" required value="${e(c.name)}" placeholder="과목명을 입력하세요"></label><div class="s-form-grid"><label class="s-form-field">학년<select name="grade">${[1,2,3,4].map(g=>`<option value="${g}" ${c.grade===g?'selected':''}>${g}학년</option>`).join('')}</select></label><label class="s-form-field">학기<select name="semester">${['1','2'].map(s=>`<option value="${s}" ${c.semester===s?'selected':''}>${s}학기</option>`).join('')}</select></label></div><label class="s-form-field">수강 연도 · 선택<input name="year" type="number" min="2000" max="2100" value="${e(c.year)}" placeholder="예: 2026"></label><button class="s-btn teal" type="submit">${id?'변경 저장':'과목 추가'}</button></form>`);q('#s-course-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),name=String(f.get('name')).trim(),grade=+f.get('grade'),semester=String(f.get('semester')),year=String(f.get('year')).trim();if(!name)return;if(state.courses.some(x=>x.id!==id&&x.name===name&&x.grade===grade&&x.semester===semester&&x.year===year)){notify('같은 학기와 연도에 이미 있는 과목입니다.');return;}const nextID=id||'course-'+crypto.randomUUID();if(commit(s=>{if(id)Object.assign(s.courses.find(x=>x.id===id),{name,grade,semester,year});else s.courses.push({id:nextID,name,grade,semester,year,questions:[],exam:{mid:{},final:{}}});})){modal.close();viewYear='';go(url(nextID));}};}
function bindCourse(c){if(q('#s-edit-course'))q('#s-edit-course').onclick=()=>courseDialog(c.id);if(q('#s-material-mode'))q('#s-material-mode').onclick=()=>{archiveView=!archiveView;renderCourse(c);};qa('[data-preview]').forEach(b=>b.onclick=()=>preview(state.materials.find(m=>m.id===b.dataset.preview)));qa('[data-archive],[data-restore]').forEach(b=>b.onclick=()=>{const id=b.dataset.archive||b.dataset.restore;if(commit(s=>s.materials.find(m=>m.id===id).archived=!!b.dataset.archive))renderCourse(course(c.id));});if(q('#s-material-form'))q('#s-material-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),file=f.get('file');if(!file||!file.size){notify('원본 파일을 골라 주세요.');return;}if(file.size>30*1024*1024){notify('파일당 30MB 이내로 등록해 주세요.');return;}if(!/\.(pdf|txt|md|csv|png|jpg|jpeg|webp|docx|pptx|xlsx)$/i.test(file.name)){notify('PDF·텍스트·이미지·Office 형식의 자료를 선택해 주세요.');return;}const button=ev.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='자료를 보관하는 중…';try{const id='file-'+crypto.randomUUID(),title=String(f.get('title')).trim()||file.name,week=String(f.get('week')).trim(),pages=f.get('pages')?+f.get('pages'):null;await putFile(id,file);if(commit(s=>s.materials.push({id,course:c.id,title,week,pages,filename:file.name,size:file.size,builtin:false,archived:false}))){if(activeCourse===c.id&&activeTab==='materials'){renderCourse(course(c.id));}notify('이 과목에 자료를 보관했습니다. 시험범위는 따로 지정하세요.');}}catch(err){notify(err.message);}finally{if(button.isConnected){button.disabled=false;button.textContent='이 과목에 자료 보관';}}};qa('[data-exam]').forEach(b=>b.onclick=()=>{examType=b.dataset.exam;examViews[c.id]=examType;renderCourse(c);});if(q('#s-scope-form'))q('#s-scope-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),scope={};try{for(const id of f.getAll('include')){const m=state.materials.find(m=>m.id===id),input=qa('[data-scope-range]').find(x=>x.dataset.scopeRange===id),text=input.value.trim();rangePages(text,m.pages);scope[id]=text;}}catch(err){notify(err.message);return;}if(commit(s=>{const target=s.courses.find(x=>x.id===c.id);target.exam??={mid:{},final:{}};target.exam[examType]=scope;})){renderCourse(course(c.id));notify('시험범위를 저장했습니다.');}};qa('[data-question]').forEach(input=>input.onchange=()=>{if(commit(s=>{s.courses.find(x=>x.id===c.id).questions.find(n=>n.id===input.dataset.question).resolved=input.checked;}))renderCourse(course(c.id));});if(q('#s-question-form'))q('#s-question-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),text=String(f.get('text')).trim(),source=String(f.get('source')).trim();if(!text)return;if(commit(s=>{const c2=s.courses.find(x=>x.id===c.id);c2.questions??=[];c2.questions.push({id:crypto.randomUUID(),text,source,resolved:false});})){renderCourse(course(c.id));notify('확인할 내용을 이 과목에 기록했습니다.');}};}
function route(){window.PLLab?.stop();routeNumber++;const h=location.hash;document.body.classList.remove('s-menu-open');if(/^#w\d+\/\d+/.test(h)){activeCourse=null;const[u,n,t]=h.slice(1).split('/');root.hidden=true;document.body.classList.remove('lib-view');window.UnixReader.open(u,+n,t||'learn');return;}window.UnixReader.pause();root.hidden=false;document.body.classList.add('lib-view');const p=h.replace(/^#\/?/,'').split('/');if(p[0]==='course'){const c=course(decodeURIComponent(p[1]||''));if(!c){go('#/library/2/2');return;}activeCourse=c.id;examType=examViews[c.id]||'mid';activeTab=tabs.some(x=>x[0]===p[2])?p[2]:'home';viewGrade=c.grade;viewSemester=c.semester;archiveView=false;renderCourse(c);}else{activeCourse=null;viewGrade=p[1]==='all'?'all':[1,2,3,4].includes(+p[1])?+p[1]:2;viewSemester=p[2]==='all'?'all':['1','2'].includes(p[2])?p[2]:'2';renderShelf();}window.scrollTo({top:0,behavior:'instant'});}
const back=document.createElement('a');back.id='library-back';back.href=url('unix');back.innerHTML=icon('back')+'과목 홈 · 학습 서재';q('#sidebar').insertBefore(back,q('#sidebar').firstChild);
q('.skip').onclick=ev=>{ev.preventDefault();const target=q(document.body.classList.contains('lib-view')?'#s-content':'#content');target.focus();target.scrollIntoView({block:'start'});};
window.addEventListener('hashchange',route);window.addEventListener('pageshow',()=>{if(document.body.classList.contains('lib-view'))route();});route();
window.StudyLibrary={rangePages};
})();
